import sys
from typing import List, Tuple

def max_fruits_sliced(n: int, fruits: List[Tuple[float, float]]) -> int:
    def orientation(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> float:
        return (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])

    def count_circles_on_line(p: Tuple[float, float], q: Tuple[float, float]) -> int:
        count = 0
        for fruit in fruits:
            if abs(orientation(p, q, fruit)) <= 1e-9:
                count += 1
        return count

    def max_circles_in_half_plane(p: Tuple[float, float], q: Tuple[float, float]) -> int:
        max_count = 0
        for fruit in fruits:
            if orientation(p, q, fruit) > 0:
                max_count += 1
        return max_count

    def find_best_slice(start: int, end: int) -> int:
        if start == end:
            return 1
        mid = (start + end) // 2
        left_max = find_best_slice(start, mid)
        right_max = find_best_slice(mid + 1, end)
        max_cross = 0

        left_points = sorted(fruits[start:mid + 1], key=lambda x: (x[0], x[1]))
        right_points = sorted(fruits[mid + 1:end + 1], key=lambda x: (x[0], x[1]))

        for i in range(len(left_points)):
            for j in range(len(right_points)):
                p, q = left_points[i], right_points[j]
                count = count_circles_on_line(p, q)
                max_cross = max(max_cross, count + max_circles_in_half_plane(p, q) + max_circles_in_half_plane(q, p))

        return max(left_max, right_max, max_cross)

    return find_best_slice(0, n - 1)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    fruits = []
    index = 1
    for _ in range(n):
        x = float(data[index])
        y = float(data[index + 1])
        fruits.append((x, y))
        index += 2

    result = max_fruits_sliced(n, fruits)
    print(result)

